            if pseudo_name=='first-of-type':
                if not node.parent:
                    return False
                for child in node.parent.children:
                    if child.is_element and child.tag==node.tag:
                        if child is node:
                            break
                        else:
                            return False
            elif pseudo_name=='last-of-type':
                if not node.parent:
                    return False
                for child in reversed(node.parent.children):
                    if child.is_element and child.tag==node.tag:
                        if child is node:
                            break
                        else:
                            return False
            elif pseudo_name=='nth-child':
                if not node.parent:
                    return False
                idx=0
                for child in node.parent.children:
                    if child.is_element:
                        idx+=1
                        if child is node:
                            break
                arg = pseudo_arg.strip() if pseudo_arg else ""
                if arg=="odd":
                    if idx%2==0:
                        return False
                elif arg=="even":
                    if idx%2==1:
                        return False
                else:
                    try:
                        n=int(arg)
                        if idx!=n:
                            return False
                    except:
                        return False
            else:
                return False
    return True

def parse_selector_group(s):
    s=s.strip()
    if not s:
        return None
    parts=[]
    current_combinator=None
    simple_buf=""
    in_bracket=0
    in_paren=0
    in_quote=None
    i=0
    n=len(s)
    while i<n:
        c=s[i]
        if in_quote:
            if c==in_quote:
                in_quote=None
            simple_buf+=c
            i+=1
            continue
        if c in ('"',"'"):
            in_quote=c
            simple_buf+=c
            i+=1
            continue
        if c=='[':
            in_bracket+=1
            simple_buf+=c
            i+=1
            continue
        if c==']':
            in_bracket-=1
            simple_buf+=c
            i+=1
            continue
        if c=='(':
            in_paren+=1
            simple_buf+=c
            i+=1
            continue
        if c==')':
            in_paren-=1
            simple_buf+=c
            i+=1
            continue
        if in_bracket==0 and in_paren==0:
            if c in ('>','+','~'):
                if simple_buf.strip():
                    simple=parse_simple_selector(simple_buf.strip())
                    if simple is None:
                        return None
                    parts.append((current_combinator, simple))
                    simple_buf=""
                current_combinator=c
                i+=1
                while i<n and s[i].isspace():
                    i+=1
                continue
            elif c.isspace():
                j=i+1
                while j<n and s[j].isspace():
                    j+=1
                if j<n and s[j] in ('>','+','~'):
                    i=j
                    continue
                else:
                    if simple_buf.strip():
                        simple=parse_simple_selector(simple_buf.strip())
                        if simple is None:
                            return None
                        parts.append((current_combinator, simple))
                        simple_buf=""
                    current_combinator=' '
                    i+=1
                    while i<n and s[i].isspace():
                        i+=1
                    continue
        simple_buf+=c
        i+=1
    if simple_buf.strip():
        simple=parse_simple_selector(simple_buf.strip())
        if simple is None:
            return None
        parts.append((current_combinator, simple))
    return parts

def selector_matches(node, parts):
    def match_at(n, idx):
        if idx<0:
            return True
        comb, simple = parts[idx]
        if not match_simple(n, simple):
            return False
        if idx==0:
            return True
        prev_comb = parts[idx][0]
        if prev_comb==' ' or prev_comb is None:
            parent=n.parent
            while parent:
                if match_at(parent, idx-1):
                    return True
                parent=parent.parent
            return False
        elif prev_comb=='>':
            parent=n.parent
            if not parent:
                return False
            return match_at(parent, idx-1)
        elif prev_comb=='+':
            if not n.parent:
                return False
            prev=None
            for child in n.parent.children:
                if child is n:
                    break
                if child.is_element:
                    prev=child
            if not prev:
                return False
            return match_at(prev, idx-1)
        elif prev_comb=='~':
            if not n.parent:
                return False
            for child in n.parent.children:
                if child is n:
                    break
                if child.is_element:
                    if match_at(child, idx-1):
                        return True
            return False
        else:
            return False
    return match_at(node, len(parts)-1)

def split_selectors(s):
    groups=[]
    current=""
    in_bracket=0
    in_paren=0
    in_quote=None
    i=0
    n=len(s)
    while i<n:
        c=s[i]
        if in_quote:
            if c==in_quote:
                in_quote=None
            current+=c
        elif c in ('"',"'"):
            in_quote=c
            current+=c
        elif c=='[':
            in_bracket+=1
            current+=c
        elif c==']':
            in_bracket-=1
            current+=c
        elif c=='(':
            in_paren+=1
            current+=c
        elif c==')':
            in_paren-=1
            current+=c
        elif c==',' and in_bracket==0 and in_paren==0:
            groups.append(current.strip())
            current=""
        else:
            current+=c
        i+=1
    if current.strip():
        groups.append(current.strip())
    return groups

def parse_selectors(s):
    if not s.strip():
        return None
    group_strs=split_selectors(s)
    all_groups=[]
    for g in group_strs:
        if not g:
            return None
        parts=parse_selector_group(g)
        if parts is None:
            return None
        all_groups.append(parts)
    return all_groups

def find_matching_nodes(root, selector_groups):
    matched=[]
    seen=set()
    def dfs(node):
        if node.is_element:
            for group in selector_groups:
                if selector_matches(node, group):
                    if id(node) not in seen:
                        seen.add(id(node))
                        matched.append(node)
                    break
        for child in node.children:
            dfs(child)
    dfs(root)
    return matched

def get_base_url_simple(root, detect_base, base_arg):
    base_tag_href=None
    if detect_base:
        def dfs(node):
            nonlocal base_tag_href
            if base_tag_href is not None:
                return
            if node.is_element and node.tag=='base':
                href=node.get_attr('href')
                if href:
                    base_tag_href=href
                    return
            for child in node.children:
                dfs(child)
        dfs(root)
        if base_tag_href:
            try:
                p=urlparse(base_tag_href)
                if p.scheme and p.netloc:
                    return base_tag_href
            except:
                pass
    if base_arg:
        try:
            p=urlparse(base_arg)
            if p.scheme and p.netloc:
                return base_arg
        except:
            pass
    return None

def resolve_url(base, href):
    if not base:
        return href
    try:
        return urljoin(base, href)
    except:
        return href

def serialize_node_with_base_rewrite(node, base_url, is_selected_root=True):
    void_elements = {"area", "base", "br", "col", "embed", "hr", "img", "input", "link", "meta", "param", "source", "track", "wbr"}
    def serialize(n, is_root):
        if n.is_text:
            return n.text
        if n.is_comment:
            return f"<!--{n.text}-->"
        if n.tag=="document":
            return "".join(serialize(child, False) for child in n.children)
        attrs=dict(n.attrs)
        if is_root and base_url and n.tag in ('a','area','link'):
            href=attrs.get('href')
            if href is not None:
                attrs['href']=resolve_url(base_url, href)
        attr_parts=[]
        for k,v in attrs.items():
            v_esc=v.replace('"','&quot;')
            attr_parts.append(f'{k}="{v_esc}"')
        attr_str=""
        if attr_parts:
            attr_str=" "+" ".join(attr_parts)
        if n.tag in void_elements:
            return f"<{n.tag}{attr_str}>"
        children_str="".join(serialize(child, False) for child in n.children)
        return f"<{n.tag}{attr_str}>{children_str}</{n.tag}>"
    return serialize(node, is_selected_root)

