            # Let's attempt simple pretty: just call serialize with base rewrite and add newline at start
            # For better, we will attempt to implement a better pretty that matches some observed cases

            def pretty_serialize(n, lvl, is_root_sel):
                indent="  "*lvl
                if n.is_text:
                    if is_whitespace(n.text):
                        return ""
                    return n.text
                if n.is_comment:
                    return f"{indent}<!--{n.text}-->"
                if n.tag=="document":
                    return "".join(pretty_serialize(ch, lvl, False) for ch in n.children)
                attrs=dict(n.attrs)
                if is_root_sel and base_url and n.tag in ('a','area','link'):
                    href=attrs.get('href')
                    if href is not None:
                        attrs['href']=resolve_url(base_url, href)
                attr_parts=[]
