def is_ws(s):
    return s.strip() == ""

def serialize_attrs(attrs):
    parts=[]
    for k,v in attrs.items():
        v_esc=v.replace('"','&quot;')
        parts.append(f'{k}="{v_esc}"')
    return " "+" ".join(parts) if parts else ""

void_elements = {"area", "base", "br", "col", "embed", "hr", "img", "input", "link", "meta", "param", "source", "track", "wbr"}
inline_tags = {'a', 'abbr', 'acronym', 'b', 'bdo', 'big', 'button', 'cite', 'code', 'dfn', 'em', 'i', 'kbd', 'label', 'map', 'object', 'output', 'q', 'samp', 'script', 'select', 'small', 'span', 'strong', 'sub', 'sup', 'textarea', 'time', 'tt', 'var'}

def pretty_node(node, level, is_html_root):
    indent = "  " * level
    if node.is_text:
        if is_ws(node.text):
            return ""
        return node.text
    if node.is_comment:
        return f"{indent}<!--{node.text}-->"
    if node.tag == "document":
        return "".join(pretty_node(ch, level, is_html_root) for ch in node.children)

    attrs_str = serialize_attrs(node.attrs)
    if node.tag in void_elements:
        return f"{indent}<{node.tag}{attrs_str}>\n"

    # collect element children
    elem_children = [c for c in node.children if c.is_element]
    text_children = [c for c in node.children if c.is_text and not is_ws(c.text)]
    has_elem = len(elem_children) > 0
    # inner text concatenation for only-text case
    if not has_elem:
        inner = "".join(c.text if c.is_text else f"<!--{c.text}-->" for c in node.children)
        if is_ws(inner):
            # empty
            return f"{indent}<{node.tag}{attrs_str}>\n{indent}</{node.tag}>\n"
        # only text
        if is_html_root:
            # html root mode: block vs inline
            if node.tag in inline_tags:
                # opening alone, text+closing same line on next line?
                # Observed for html root with span: "<span>\n      hi</span>\n"
                # So opening alone on line, then indent+1 + text + closing
                inner_indent = "  " * (level+1)
                # For inline, text and closing same line
                return f"{indent}<{node.tag}{attrs_str}>\n{inner_indent}{inner}</{node.tag}>\n"
            else:
                # block: opening alone, text new line, closing new line
                inner_indent = "  " * (level+1)
                return f"{indent}<{node.tag}{attrs_str}>\n{inner_indent}{inner}\n{indent}</{node.tag}>\n"
        else:
            # fragment mode: opening + text + newline + closing
            # For inline, closing same line? For span fragment, "<span>hi</span>\n" all same line
            # For block fragment, "<div>text\n</div>\n" opening+text same line, closing new line
            if node.tag in inline_tags:
                return f"{indent}<{node.tag}{attrs_str}>{inner}</{node.tag}>\n"
            else:
                return f"{indent}<{node.tag}{attrs_str}>{inner}\n{indent}</{node.tag}>\n"
    else:
        # has element children
        # For html root vs fragment, behavior differs
        # For fragment, block children on new line, inline same line? Let's attempt
        out = f"{indent}<{node.tag}{attrs_str}>\n"
        for child in node.children:
            if child.is_text and is_ws(child.text):
                continue
            if child.is_element:
                out += pretty_node(child, level+1, is_html_root)
            elif child.is_text:
                # text inside element with element children
                # For html root: text on new line indented?
                # For fragment: ?
                # For <p>Hello <b>world</b></p> fragment pretty: "<p>Hello <b>world</b>\n</p>\n" -> text and inline same line as opening? Actually p opening and text same line
                # For html root same case: "<p>\n      Hello <b>world</b>\n    </p>\n" -> text on new line

                if is_html_root:
                    out += "  " * (level+1) + child.text + "\n"
                else:
                    # fragment: text same line as previous? For simplicity, put text with indent
                    out += "  " * (level+1) + child.text + "\n"
            elif child.is_comment:
                out += "  " * (level+1) + f"<!--{child.text}-->\n"
        out += f"{indent}</{node.tag}>\n"
        return out

