    except ValueError:
        dd_idx = len(argv)
    pos=0
    for idx in range(dd_idx):
        token=argv[idx]
        if token=='--help' or token=='-h':
            if first_help_pos is None:
                first_help_pos=pos
        elif token=='--version' or token=='-V':
            if first_version_pos is None:
                first_version_pos=pos
        elif token.startswith('--'):
            if token.startswith('--help'):
                if first_help_pos is None:
                    first_help_pos=pos
            elif token.startswith('--version'):
                if first_version_pos is None:
                    first_version_pos=pos
        elif token.startswith('-') and len(token)>1:
            if token=='-':
                pass
            else:
                chars=token[1:]
                j=0
                while j<len(chars):
                    c=chars[j]
                    if c in ('B','w','p','t','h','V'):
                        if c=='h' and first_help_pos is None:
                            first_help_pos=pos
                        elif c=='V' and first_version_pos is None:
                            first_version_pos=pos
