def parse_simple_selector(s):
    if not s:
        return None
    tag = None
    id_ = None
    classes = []
    attrs = []
    pseudos = []
    i=0
    n=len(s)
    while i<n:
        c=s[i]
        if c=='#':
            i+=1
            start=i
            while i<n and (s[i].isalnum() or s[i] in ('-','_')):
                i+=1
            if start==i:
                return None
            id_=s[start:i]
        elif c=='.':
            i+=1
            start=i
            while i<n and (s[i].isalnum() or s[i] in ('-','_')):
                i+=1
            if start==i:
                return None
            classes.append(s[start:i])
        elif c=='[':
            j=i+1
            in_quote=None
            while j<n:
                if s[j]==in_quote:
                    in_quote=None
                elif in_quote is None and s[j] in ('"',"'"):
                    in_quote=s[j]
                elif in_quote is None and s[j]==']':
                    break
                j+=1
            if j>=n or s[j]!=']':
                return None
            attr_content=s[i+1:j].strip()
            op=None
            name=None
            value=None
            for cand in ['~=','|=', '^=', '$=', '*=', '=']:
                if cand in attr_content:
                    parts=attr_content.split(cand,1)
                    if len(parts)==2:
                        name=parts[0].strip()
                        value=parts[1].strip()
                        op=cand
                        break
            if op is None:
                name=attr_content.strip()
                op='exists'
            else:
                if value and len(value)>=2 and ((value[0]=='"' and value[-1]=='"') or (value[0]=="'" and value[-1]=="'")):
                    value=value[1:-1]
            if not name:
                return None
            attrs.append((name.lower(), op, value))
            i=j+1
        elif c==':':
            i+=1
            if i<n and s[i]==':':
                i+=1
            start=i
            while i<n and (s[i].isalnum() or s[i] in ('-','_')):
                i+=1
            if start==i:
                return None
            pseudo_name=s[start:i].lower()
            pseudo_arg=None
            if i<n and s[i]=='(':
                j=i+1
                depth=1
                in_quote=None
                while j<n:
                    if s[j]==in_quote:
                        in_quote=None
                    elif in_quote is None and s[j] in ('"',"'"):
                        in_quote=s[j]
                    elif in_quote is None:
                        if s[j]=='(':
                            depth+=1
                        elif s[j]==')':
                            depth-=1
                            if depth==0:
                                break
                    j+=1
                if j>=n or s[j]!=')':
                    return None
                pseudo_arg=s[i+1:j]
                i=j+1
            pseudos.append((pseudo_name, pseudo_arg))
        else:
