def parse_simple_selector(s):
    if not s:
        return None
    tag = None
    id_ = None
    classes = []
    attrs = []
    pseudos = []
    i=0
    n=len(s)
    while i<n:
        c=s[i]
        if c=='#':
            i+=1
            start=i
            while i<n and (s[i].isalnum() or s[i] in ('-','_')):
                i+=1
            if start==i:
                return None
            id_=s[start:i]
        elif c=='.':
            i+=1
            start=i
            while i<n and (s[i].isalnum() or s[i] in ('-','_')):
                i+=1
            if start==i:
                return None
            classes.append(s[start:i])
        elif c=='[':
            j=i+1
            in_quote=None
            while j<n:
                if s[j]==in_quote:
                    in_quote=None
                elif in_quote is None and s[j] in ('"',"'"):
                    in_quote=s[j]
                elif in_quote is None and s[j]==']':
                    break
                j+=1
            if j>=n or s[j]!=']':
                return None
            attr_content=s[i+1:j].strip()
            op=None
            name=None
            value=None
            for cand in ['~=','|=', '^=', '$=', '*=', '=']:
                if cand in attr_content:
                    parts=attr_content.split(cand,1)
                    if len(parts)==2:
                        name=parts[0].strip()
                        value=parts[1].strip()
                        op=cand
                        break
            if op is None:
                name=attr_content.strip()
                op='exists'
            else:
                if value and len(value)>=2 and ((value[0]=='"' and value[-1]=='"') or (value[0]=="'" and value[-1]=="'")):
                    value=value[1:-1]
            if not name:
                return None
            attrs.append((name.lower(), op, value))
            i=j+1
        elif c==':':
            i+=1
            if i<n and s[i]==':':
                i+=1
            start=i
            while i<n and (s[i].isalnum() or s[i] in ('-','_')):
                i+=1
            if start==i:
                return None
            pseudo_name=s[start:i].lower()
            pseudo_arg=None
            if i<n and s[i]=='(':
                j=i+1
                depth=1
                in_quote=None
                while j<n:
                    if s[j]==in_quote:
                        in_quote=None
                    elif in_quote is None and s[j] in ('"',"'"):
                        in_quote=s[j]
                    elif in_quote is None:
                        if s[j]=='(':
                            depth+=1
                        elif s[j]==')':
                            depth-=1
                            if depth==0:
                                break
                    j+=1
                if j>=n or s[j]!=')':
                    return None
                pseudo_arg=s[i+1:j]
                i=j+1
            pseudos.append((pseudo_name, pseudo_arg))
        else:
            if tag is not None:
                return None
            start=i
            while i<n and (s[i].isalnum() or s[i] in ('-','_','*')):
                i+=1
            if start==i:
                return None
            tag_candidate=s[start:i]
            tag=tag_candidate.lower()
    if tag is None and id_ is None and not classes and not attrs and not pseudos:
        return None
    return {'tag':tag,'id':id_,'classes':classes,'attrs':attrs,'pseudos':pseudos}

def match_simple(node, simple):
    if not node.is_element:
        return False
    tag=simple['tag']
    if tag is not None and tag!='*' and node.tag!=tag:
        return False
    if simple['id'] is not None:
        if node.get_id()!=simple['id']:
            return False
    node_classes=node.get_classes()
    for cls in simple['classes']:
        if cls not in node_classes:
            return False
    for attr_name, op, val in simple['attrs']:
        node_val=node.get_attr(attr_name)
        if op=='exists':
            if node_val is None:
                return False
        elif op=='=':
            if node_val!=val:
                return False
        elif op=='~=':
            if node_val is None or val not in node_val.split():
                return False
        elif op=='|=':
            if node_val is None or (node_val!=val and not node_val.startswith(val+'-')):
                return False
        elif op=='^=':
            if node_val is None or not node_val.startswith(val):
                return False
        elif op=='$=':
            if node_val is None or not node_val.endswith(val):
                return False
        elif op=='*=':
            if node_val is None or val not in node_val:
                return False
        else:
            return False
    for pseudo_name, pseudo_arg in simple['pseudos']:
        if pseudo_name=='first-child':
            if not node.parent:
                return False
            for child in node.parent.children:
                if child.is_element:
                    if child is node:
                        break
                    else:
                        return False
        elif pseudo_name=='last-child':
            if not node.parent:
                return False
            for child in reversed(node.parent.children):
                if child.is_element:
                    if child is node:
                        break
                    else:
                        return False
        elif pseudo_name=='only-child':
            if not node.parent:
                return False
            cnt=0
            for child in node.parent.children:
                if child.is_element:
                    cnt+=1
            if cnt!=1:
                return False
        elif pseudo_name=='empty':
            if node.children:
                for child in node.children:
                    if child.is_element:
                        return False
                    if child.is_text and not is_whitespace(child.text):
                        return False
        elif pseudo_name=='root':
            if node.tag!='html':
                return False
        else:
            if pseudo_name=='first-of-type':
                if not node.parent:
                    return False
                for child in node.parent.children:
                    if child.is_element and child.tag==node.tag:
                        if child is node:
                            break
                        else:
                            return False
            elif pseudo_name=='last-of-type':
                if not node.parent:
                    return False
                for child in reversed(node.parent.children):
                    if child.is_element and child.tag==node.tag:
                        if child is node:
                            break
                        else:
                            return False
            elif pseudo_name=='nth-child':
                if not node.parent:
                    return False
                idx=0
                for child in node.parent.children:
                    if child.is_element:
                        idx+=1
                        if child is node:
                            break
                arg = pseudo_arg.strip() if pseudo_arg else ""
                if arg=="odd":
                    if idx%2==0:
                        return False
                elif arg=="even":
                    if idx%2==1:
                        return False
                else:
                    try:
                        n=int(arg)
                        if idx!=n:
                            return False
                    except:
                        return False
            else:
                return False
    return True

def parse_selector_group(s):
    s=s.strip()
    if not s:
        return None
    parts=[]
    current_combinator=None
    simple_buf=""
    in_bracket=0
    in_paren=0
    in_quote=None
    i=0
    n=len(s)
    while i<n:
        c=s[i]
        if in_quote:
            if c==in_quote:
                in_quote=None
            simple_buf+=c
            i+=1
            continue
        if c in ('"',"'"):
            in_quote=c
            simple_buf+=c
            i+=1
            continue
        if c=='[':
            in_bracket+=1
            simple_buf+=c
            i+=1
            continue
        if c==']':
            in_bracket-=1
            simple_buf+=c
            i+=1
            continue
        if c=='(':
            in_paren+=1
            simple_buf+=c
            i+=1
            continue
        if c==')':
            in_paren-=1
            simple_buf+=c
            i+=1
            continue
        if in_bracket==0 and in_paren==0:
            if c in ('>','+','~'):
                if simple_buf.strip():
                    simple=parse_simple_selector(simple_buf.strip())
                    if simple is None:
                        return None
                    parts.append((current_combinator, simple))
                    simple_buf=""
                current_combinator=c
                i+=1
                while i<n and s[i].isspace():
                    i+=1
                continue
            elif c.isspace():
                j=i+1
                while j<n and s[j].isspace():
                    j+=1
                if j<n and s[j] in ('>','+','~'):
                    i=j
                    continue
                else:
                    if simple_buf.strip():
                        simple=parse_simple_selector(simple_buf.strip())
                        if simple is None:
                            return None
                        parts.append((current_combinator, simple))
                        simple_buf=""
                    current_combinator=' '
                    i+=1
                    while i<n and s[i].isspace():
                        i+=1
                    continue
        simple_buf+=c
        i+=1
    if simple_buf.strip():
        simple=parse_simple_selector(simple_buf.strip())
        if simple is None:
            return None
        parts.append((current_combinator, simple))
    return parts

def selector_matches(node, parts):
    def match_at(n, idx):
        if idx<0:
            return True
        comb, simple = parts[idx]
        if not match_simple(n, simple):
            return False
        if idx==0:
            return True
        prev_comb = parts[idx][0]
        if prev_comb==' ' or prev_comb is None:
            parent=n.parent
            while parent:
                if match_at(parent, idx-1):
                    return True
                parent=parent.parent
            return False
        elif prev_comb=='>':
            parent=n.parent
            if not parent:
                return False
            return match_at(parent, idx-1)
        elif prev_comb=='+':
            if not n.parent:
                return False
            prev=None
            for child in n.parent.children:
                if child is n:
                    break
                if child.is_element:
                    prev=child
            if not prev:
                return False
            return match_at(prev, idx-1)
        elif prev_comb=='~':
            if not n.parent:
                return False
            for child in n.parent.children:
                if child is n:
                    break
                if child.is_element:
                    if match_at(child, idx-1):
                        return True
            return False
        else:
            return False
    return match_at(node, len(parts)-1)

def split_selectors(s):
    groups=[]
    current=""
    in_bracket=0
    in_paren=0
    in_quote=None
    i=0
    n=len(s)
    while i<n:
        c=s[i]
        if in_quote:
            if c==in_quote:
                in_quote=None
            current+=c
        elif c in ('"',"'"):
            in_quote=c
            current+=c
        elif c=='[':
            in_bracket+=1
            current+=c
        elif c==']':
            in_bracket-=1
            current+=c
        elif c=='(':
            in_paren+=1
            current+=c
        elif c==')':
            in_paren-=1
            current+=c
        elif c==',' and in_bracket==0 and in_paren==0:
            groups.append(current.strip())
            current=""
        else:
            current+=c
        i+=1
    if current.strip():
        groups.append(current.strip())
    return groups

def parse_selectors(s):
    if not s.strip():
        return None
    group_strs=split_selectors(s)
    all_groups=[]
    for g in group_strs:
        if not g:
            return None
        parts=parse_selector_group(g)
        if parts is None:
            return None
        all_groups.append(parts)
    return all_groups

def find_matching_nodes(root, selector_groups):
    matched=[]
    seen=set()
    def dfs(node):
        if node.is_element:
            for group in selector_groups:
                if selector_matches(node, group):
                    if id(node) not in seen:
                        seen.add(id(node))
                        matched.append(node)
                    break
        for child in node.children:
            dfs(child)
    dfs(root)
    return matched

def get_base_url_simple(root, detect_base, base_arg):
    base_tag_href=None
    if detect_base:
        def dfs(node):
            nonlocal base_tag_href
            if base_tag_href is not None:
                return
            if node.is_element and node.tag=='base':
                href=node.get_attr('href')
                if href:
                    base_tag_href=href
                    return
            for child in node.children:
                dfs(child)
        dfs(root)
        if base_tag_href:
            try:
                p=urlparse(base_tag_href)
                if p.scheme and p.netloc:
                    return base_tag_href
            except:
                pass
    if base_arg:
        try:
            p=urlparse(base_arg)
            if p.scheme and p.netloc:
                return base_arg
        except:
            pass
    return None

def resolve_url(base, href):
    if not base:
        return href
    try:
        joined = urljoin(base, href)
        p = urlparse(joined)
        if p.scheme and p.netloc and not p.path:
            joined = urlunparse((p.scheme, p.netloc, "/", p.params, p.query, p.fragment))
        return joined
    except:
        return href

def serialize_node_with_base_rewrite(node, base_url, is_selected_root=True):
    void_elements = {"area", "base", "br", "col", "embed", "hr", "img", "input", "link", "meta", "param", "source", "track", "wbr"}
    def serialize(n, is_root):
        if n.is_text:
            return n.text
        if n.is_comment:
            return f"<!--{n.text}-->"
        if n.tag=="document":
            return "".join(serialize(child, False) for child in n.children)
        attrs=dict(n.attrs)
        if is_root and base_url and n.tag in ('a','area','link'):
            href=attrs.get('href')
            if href is not None:
                attrs['href']=resolve_url(base_url, href)
        attr_parts=[]
        for k,v in attrs.items():
            v_esc=v.replace('"','&quot;')
            attr_parts.append(f'{k}="{v_esc}"')
        attr_str=""
        if attr_parts:
            attr_str=" "+" ".join(attr_parts)
        if n.tag in void_elements:
            return f"<{n.tag}{attr_str}>"
        children_str="".join(serialize(child, False) for child in n.children)
        return f"<{n.tag}{attr_str}>{children_str}</{n.tag}>"
    return serialize(node, is_selected_root)

