                    first_version_pos=pos
        elif token.startswith('-') and len(token)>1:
            if token=='-':
                pass
            else:
                chars=token[1:]
                j=0
                while j<len(chars):
                    c=chars[j]
                    if c in ('B','w','p','t','h','V'):
                        if c=='h' and first_help_pos is None:
                            first_help_pos=pos
                        elif c=='V' and first_version_pos is None:
                            first_version_pos=pos
                        j+=1
                    elif c in ('a','b','f','o','r'):
                        break
                    else:
                        break
        pos+=1

    if first_help_pos is not None or first_version_pos is not None:
        if first_help_pos is not None and first_version_pos is not None:
            if first_help_pos < first_version_pos:
