                    if i+1>=len(argv):
                        error_missing_value('--base <base>', usages['base'])
                    val=argv[i+1]
                    i+=1
                if not val:
                    error_missing_value('--base <base>', usages['base'])
                seen['base']=True
                base=val
            elif name=='--filename':
                if seen['filename']:
                    error_duplicate('--filename <FILE>', usages['filename'])
                if val is None:
                    if i+1>=len(argv):
                        error_missing_value('--filename <FILE>', usages['filename'])
                    val=argv[i+1]
                    i+=1
                if not val:
                    error_missing_value('--filename <FILE>', usages['filename'])
                seen['filename']=True
                filename=val
            elif name=='--output':
                if seen['output']:
                    error_duplicate('--output <FILE>', usages['output'])
                if val is None:
                    if i+1>=len(argv):
                        error_missing_value('--output <FILE>', usages['output'])
                    val=argv[i+1]
                    i+=1
                if not val:
                    error_missing_value('--output <FILE>', usages['output'])
                seen['output']=True
                output=val
            elif name=='--remove-nodes':
                if val is None:
                    if i+1>=len(argv):
                        error_missing_value('--remove-nodes <SELECTOR>...', usages['remove-nodes'])
