                if not val:
                    error_missing_value('--remove-nodes <SELECTOR>...', usages['remove-nodes'])
                remove_nodes.append(val)
            else:
                error_unknown(token)
        elif token.startswith('-') and len(token)>1:
            if '=' in token and len(token)>=3 and token[2]=='=':
                opt_char=token[1]
                val=token[3:]
                if opt_char=='a':
                    if seen['attribute']:
                        error_duplicate('--attribute <attribute>', usages['attribute'])
                    if not val:
                        error_missing_value('--attribute <attribute>', usages['attribute'])
                    seen['attribute']=True
                    attribute=val
                elif opt_char=='b':
                    if seen['base']:
                        error_duplicate('--base <base>', usages['base'])
                    if not val:
                        error_missing_value('--base <base>', usages['base'])
                    seen['base']=True
                    base=val
                elif opt_char=='f':
                    if seen['filename']:
                        error_duplicate('--filename <FILE>', usages['filename'])
                    if not val:
                        error_missing_value('--filename <FILE>', usages['filename'])
                    seen['filename']=True
                    filename=val
                elif opt_char=='o':
                    if seen['output']:
                        error_duplicate('--output <FILE>', usages['output'])
                    if not val:
                        error_missing_value('--output <FILE>', usages['output'])
                    seen['output']=True
                    output=val
                elif opt_char=='r':
                    if not val:
                        error_missing_value('--remove-nodes <SELECTOR>...', usages['remove-nodes'])
                    remove_nodes.append(val)
                elif opt_char=='h':
                    print(help_text)
                    sys.exit(0)
                elif opt_char=='V':
                    print(version_text)
                    sys.exit(0)
                elif opt_char=='B':
                    if seen['detect-base']:
                        error_duplicate('--detect-base', usages['detect-base'])
                    seen['detect-base']=True
                    detect_base=True
                elif opt_char=='w':
                    if seen['ignore-whitespace']:
                        error_duplicate('--ignore-whitespace', usages['ignore-whitespace'])
                    seen['ignore-whitespace']=True
                    ignore_whitespace=True
                elif opt_char=='p':
                    if seen['pretty']:
                        error_duplicate('--pretty', usages['pretty'])
                    seen['pretty']=True
                    pretty=True
                elif opt_char=='t':
                    if seen['text']:
                        error_duplicate('--text', usages['text'])
                    seen['text']=True
                    text=True
                else:
                    error_unknown(token)
                i+=1
                continue
            chars=token[1:]
            j=0
            while j<len(chars):
                c=chars[j]
                if c=='B':
                    if seen['detect-base']:
                        error_duplicate('--detect-base', usages['detect-base'])
                    seen['detect-base']=True
                    detect_base=True
                    j+=1
                elif c=='w':
                    if seen['ignore-whitespace']:
                        error_duplicate('--ignore-whitespace', usages['ignore-whitespace'])
                    seen['ignore-whitespace']=True
                    ignore_whitespace=True
                    j+=1
                elif c=='p':
                    if seen['pretty']:
                        error_duplicate('--pretty', usages['pretty'])
                    seen['pretty']=True
                    pretty=True
                    j+=1
                elif c=='t':
                    if seen['text']:
                        error_duplicate('--text', usages['text'])
                    seen['text']=True
                    text=True
                    j+=1
                elif c=='h':
                    print(help_text)
                    sys.exit(0)
                elif c=='V':
                    print(version_text)
                    sys.exit(0)
                elif c in ('a','b','f','o','r'):
                    val=chars[j+1:]
                    if val=="":
                        if i+1>=len(argv):
                            if c=='a':
                                error_missing_value('--attribute <attribute>', usages['attribute'])
                            elif c=='b':
                                error_missing_value('--base <base>', usages['base'])
                            elif c=='f':
                                error_missing_value('--filename <FILE>', usages['filename'])
                            elif c=='o':
                                error_missing_value('--output <FILE>', usages['output'])
                            elif c=='r':
                                error_missing_value('--remove-nodes <SELECTOR>...', usages['remove-nodes'])
                        val=argv[i+1]
                        i+=1
                    if c=='a':
                        if seen['attribute']:
                            error_duplicate('--attribute <attribute>', usages['attribute'])
                        seen['attribute']=True
                        attribute=val
                    elif c=='b':
                        if seen['base']:
                            error_duplicate('--base <base>', usages['base'])
                        seen['base']=True
                        base=val
                    elif c=='f':
                        if seen['filename']:
                            error_duplicate('--filename <FILE>', usages['filename'])
                        seen['filename']=True
                        filename=val
                    elif c=='o':
                        if seen['output']:
                            error_duplicate('--output <FILE>', usages['output'])
                        seen['output']=True
                        output=val
                    elif c=='r':
                        remove_nodes.append(val)
