        except IsADirectoryError:
            panic_file_not_found()
        except Exception:
            panic_file_not_found()
    else:
        try:
            html_input=sys.stdin.read()
        except:
            html_input=""

    root=parse_html(html_input)
    root=ensure_html_structure(root)

    for rem_sel_str in remove_nodes:
        groups=parse_selectors(rem_sel_str)
        if groups is None:
            panic_selector()
        matching=find_matching_nodes(root, groups)
        for node in matching:
            node.detach()

    base_url=get_base_url_simple(root, detect_base, base)

    main_groups=parse_selectors(selector_str)
    if main_groups is None:
        panic_selector()

    matched_nodes=find_matching_nodes(root, main_groups)

    output_content=""
    if attribute is not None:
        out=[]
        for node in matched_nodes:
            if not node.is_element:
                continue
            val=node.get_attr(attribute)
            if val is None:
                continue
            if attribute.lower()=='href' and node.tag in ('a','area','link') and base_url:
                val=resolve_url(base_url, val)
            out.append(val)
        if out:
            output_content="\n".join(out)+"\n"
    elif text:
        if ignore_whitespace:
            for node in matched_nodes:
                t_nodes=[]
                def collect(n):
                    if n.is_text:
                        t_nodes.append(n.text)
                    for c in n.children:
                        collect(c)
                collect(node)
                filtered=[t for t in t_nodes if not is_whitespace(t)]
                for t in filtered:
                    output_content+=t+"\n"
                output_content+="\n"
        else:
            for node in matched_nodes:
                t_nodes=[]
                def collect(n):
                    if n.is_text:
                        t_nodes.append(n.text)
                    for c in n.children:
                        collect(c)
                collect(node)
                concat="".join(t_nodes)
                output_content+=concat+"\n"
    else:
        if pretty:
            void_elements={"area","base","br","col","embed","hr","img","input","link","meta","param","source","track","wbr"}
            inline_tags={'a','abbr','acronym','b','bdo','big','button','cite','code','dfn','em','i','kbd','label','map','object','output','q','samp','script','select','small','span','strong','sub','sup','textarea','time','tt','var'}
            def pretty_serialize(n, lvl, is_root_sel, is_html_root):
                indent="  "*lvl
                if n.is_text:
                    if is_whitespace(n.text):
                        return ""
                    return n.text
                if n.is_comment:
                    return f"{indent}<!--{n.text}-->"
                if n.tag=="document":
                    return "".join(pretty_serialize(ch, lvl, False, is_html_root) for ch in n.children)
                attrs=dict(n.attrs)
                if is_root_sel and base_url and n.tag in ('a','area','link'):
                    href=attrs.get('href')
                    if href is not None:
                        attrs['href']=resolve_url(base_url, href)
                attr_parts=[]
                for k,v in attrs.items():
                    v_esc=v.replace('"','&quot;')
                    attr_parts.append(f'{k}="{v_esc}"')
                attr_str=" "+" ".join(attr_parts) if attr_parts else ""
                if n.tag in void_elements:
                    return f"{indent}<{n.tag}{attr_str}>\n"
                has_elem=any(ch.is_element for ch in n.children)
                if not has_elem:
                    inner="".join(ch.text if ch.is_text else f"<!--{ch.text}-->" for ch in n.children)
                    if is_whitespace(inner):
                        return f"{indent}<{n.tag}{attr_str}>\n{indent}</{n.tag}>\n"
                    if is_html_root:
                        if n.tag in inline_tags:
                            inner_indent="  "*(lvl+1)
                            return f"{indent}<{n.tag}{attr_str}>\n{inner_indent}{inner}</{n.tag}>\n"
                        else:
                            inner_indent="  "*(lvl+1)
                            return f"{indent}<{n.tag}{attr_str}>\n{inner_indent}{inner}\n{indent}</{n.tag}>\n"
                    else:
                        if n.tag in inline_tags:
                            return f"{indent}<{n.tag}{attr_str}>{inner}</{n.tag}>\n"
                        else:
                            return f"{indent}<{n.tag}{attr_str}>{inner}\n{indent}</{n.tag}>\n"
                else:
                    out=f"{indent}<{n.tag}{attr_str}>\n"
                    for ch in n.children:
                        if ch.is_text and is_whitespace(ch.text):
                            continue
                        if ch.is_element:
                            out+=pretty_serialize(ch, lvl+1, False, is_html_root)
                        elif ch.is_text:
                            out+= "  "*(lvl+1) + ch.text + "\n"
                        elif ch.is_comment:
                            out+= "  "*(lvl+1) + f"<!--{ch.text}-->\n"
                    out+=f"{indent}</{n.tag}>\n"
                    return out
            is_html_root = False
            for node in matched_nodes:
                if node.tag == 'html':
                    is_html_root = True
                    break
            if selector_str == 'html':
                is_html_root = True
            for node in matched_nodes:
                if node.tag in inline_tags:
                    output_content+=pretty_serialize(node,0,True,is_html_root)
                else:
                    output_content+="\n"+pretty_serialize(node,0,True,is_html_root)
        else:
            for node in matched_nodes:
                serialized=serialize_node_with_base_rewrite(node, base_url, True)
                output_content+=serialized+"\n"

    if output:
        try:
            with open(output,'w',encoding='utf-8') as f:
                f.write(output_content)
        except FileNotFoundError:
            panic_output_file()
        except IsADirectoryError:
            panic_output_file()
        except Exception:
            panic_output_file()
    else:
        sys.stdout.write(output_content)

if __name__=="__main__":
    main()
